    };

    private static AmbitoPersonal DeEstudiante(Usuario usuario, DirectorioAcademico directorio)
    {
        var programas = ProgramasDeEstudiante(usuario, directorio);
        var coordinadores = directorio.Coordinadores
            .Where(coordinador => coordinador.ProgramasIds.Intersect(programas).Any())
            .Select(coordinador => Clave(coordinador.Id));
        var propia = Clave(usuario.Id);
        return new AmbitoPersonal(
            new HashSet<string> { propia },
            new HashSet<string>(coordinadores) { propia });
    }

    private static AmbitoPersonal DeCoordinador(Usuario usuario, DirectorioAcademico directorio)
    {
        var programas = ProgramasDeCoordinador(usuario, directorio);
        var claves = directorio.Estudiantes
            .Where(estudiante => programas.Contains(estudiante.ProgramaId))
            .Select(estudiante => Clave(estudiante.Id))
            .Append(Clave(usuario.Id))
            .ToHashSet();
        return new AmbitoPersonal(claves, claves);
    }

    private static List<string> ProgramasDeCoordinador(Usuario usuario, DirectorioAcademico directorio) =>
        directorio.Coordinadores
            .Where(coordinador => coordinador.Id == usuario.Id)
            .SelectMany(coordinador => coordinador.ProgramasIds)
            .Where(Identificadores.EsIdPrograma)
            .Distinct()
            .ToList();

    private static List<string> ProgramasDeEstudiante(Usuario usuario, DirectorioAcademico directorio) =>
        directorio.Estudiantes
            .Where(estudiante => estudiante.Id == usuario.Id)
            .Select(estudiante => estudiante.ProgramaId)
            .Where(Identificadores.EsIdPrograma)
            .ToList();
}

using System.Text.RegularExpressions;

namespace TutorFlow.Core.Autorizacion;

internal readonly record struct MencionPersona(string Clave, int Inicio, int Fin);

public static partial class DetectorTerceros
{
    private const string MarcadorTercero = "[TERCERO]";
    private const int MinimoTokensNombreCompleto = 2;
    private static readonly string[] PrefijosId = ["est", "coord"];

    public static bool MencionaTercero(Usuario usuario, string textoNormalizado, DirectorioAcademico directorio)
    {
        var ambito = AmbitoPersonal.De(usuario, directorio);
        var tokens = TokenizadorTexto.Tokenizar(textoNormalizado);
        return MencionesDeId(tokens, directorio).Any(mencion => !ambito.ClavesDeId.Contains(mencion.Clave))
            || MencionesDeNombre(tokens, directorio).Any(mencion => !ambito.ClavesDeNombre.Contains(mencion.Clave));
    }

    public static bool TieneFormaDeIdPersona(string textoNormalizado, DirectorioAcademico directorio) =>
        MencionesDeId(TokenizadorTexto.Tokenizar(textoNormalizado), directorio).Count > 0;

    public static IReadOnlyList<string> PersonasMencionadas(string textoNormalizado, DirectorioAcademico directorio)
    {
        var tokens = TokenizadorTexto.Tokenizar(textoNormalizado);
        var idsPorClave = PersonasDelRegistro(directorio)
            .ToDictionary(persona => AmbitoPersonal.Clave(persona.Id), persona => persona.Id);
        return MencionesDeId(tokens, directorio)
            .Concat(MencionesDeNombre(tokens, directorio))
            .Where(mencion => idsPorClave.ContainsKey(mencion.Clave))
            .Select(mencion => idsPorClave[mencion.Clave])
            .Distinct()
            .ToList();
    }

    public static string EnmascararTerceros(Usuario usuario, string pregunta, DirectorioAcademico directorio)
    {
        var ambito = AmbitoPersonal.De(usuario, directorio);
        var tokens = TokenizadorTexto.Tokenizar(pregunta);
        var porId = MencionesDeId(tokens, directorio).Where(mencion => !ambito.ClavesDeId.Contains(mencion.Clave));
        var porNombre = MencionesDeNombre(tokens, directorio).Where(mencion => !ambito.ClavesDeNombre.Contains(mencion.Clave));
        var terceros = porId.Concat(porNombre).OrderByDescending(mencion => mencion.Inicio).ToList();
        return Reemplazar(pregunta, terceros);
    }

    private static string Reemplazar(string texto, List<MencionPersona> mencionesDeFinAInicio)
    {
        var limite = texto.Length;
        foreach (var mencion in mencionesDeFinAInicio.Where(mencion => mencion.Fin <= limite))
        {
            texto = string.Concat(texto.AsSpan(0, mencion.Inicio), MarcadorTercero, texto.AsSpan(mencion.Fin));
            limite = mencion.Inicio;
        }

        return texto;
    }

    private static List<MencionPersona> MencionesDeId(IReadOnlyList<TokenTexto> tokens, DirectorioAcademico directorio)
    {
        var codigos = directorio.CodigosAsignatura.Select(AmbitoPersonal.Clave).ToHashSet();
        return Enumerable.Range(0, tokens.Count)
            .Select(indice => MencionDeIdEn(tokens, indice))
            .OfType<MencionPersona>()
            .Where(mencion => !codigos.Contains(mencion.Clave))
            .ToList();
    }

    private static MencionPersona? MencionDeIdEn(IReadOnlyList<TokenTexto> tokens, int indice)
    {
        var actual = tokens[indice];
        if (IdPegado().IsMatch(actual.Valor))
        {
            return new MencionPersona(actual.Valor, actual.Inicio, actual.Fin);
        }

        var hayDigitos = indice + 1 < tokens.Count && SoloDigitos().IsMatch(tokens[indice + 1].Valor);
        return hayDigitos && PrefijosId.Contains(actual.Valor)
            ? new MencionPersona(actual.Valor + tokens[indice + 1].Valor, actual.Inicio, tokens[indice + 1].Fin)
            : null;
    }

    private static List<MencionPersona> MencionesDeNombre(IReadOnlyList<TokenTexto> tokens, DirectorioAcademico directorio) =>
        PersonasDelRegistro(directorio)
            .SelectMany(persona => MencionesDe(tokens, persona))
            .ToList();

    private static IEnumerable<MencionPersona> MencionesDe(IReadOnlyList<TokenTexto> tokens, (string Id, string Nombre) persona)
    {
        var nombre = TokenizadorTexto.Valores(persona.Nombre);
        if (nombre.Count < MinimoTokensNombreCompleto)
        {
            return [];
        }

        IReadOnlyList<string>[] ordenes = [nombre, [.. nombre.Reverse()]];
        return ordenes
            .Select(orden => (Orden: orden, Indice: TokenizadorTexto.BuscarSecuencia(tokens, orden)))
            .Where(encontrado => encontrado.Indice >= 0)
            .Select(encontrado => new MencionPersona(
                AmbitoPersonal.Clave(persona.Id),
                tokens[encontrado.Indice].Inicio,
                tokens[encontrado.Indice + encontrado.Orden.Count - 1].Fin));
    }

    private static IEnumerable<(string Id, string Nombre)> PersonasDelRegistro(DirectorioAcademico directorio) =>
        directorio.Estudiantes.Select(estudiante => (estudiante.Id, estudiante.Nombre))
            .Concat(directorio.Coordinadores.Select(coordinador => (coordinador.Id, coordinador.Nombre)));

    [GeneratedRegex(@"^(est|coord)[0-9]+\z")]
    private static partial Regex IdPegado();

    [GeneratedRegex(@"^[0-9]+\z")]
    private static partial Regex SoloDigitos();
}

using System.Text.RegularExpressions;

namespace TutorFlow.Core.Autorizacion;

public static partial class DetectorAgregados
{
    public static bool PideAgregados(string textoNormalizado) =>
        PatronesAgregados().IsMatch(textoNormalizado);

    [GeneratedRegex(
        @"\b(mejor promedio|peor promedio|ranking|que puesto|en que lugar quede|por encima de la media"
        + @"|promedio (del curso|del programa|de la carrera)|que estudiantes|todos los estudiantes"
        + @"|otros estudiantes|cuantos estudiantes)\b"
        + @"|\bcompar\w*\b.*\bcompaner\w*\b|\blist\w*\b.*\bestudiantes\b",
        RegexOptions.CultureInvariant)]
    private static partial Regex PatronesAgregados();
}

namespace TutorFlow.Core.Autorizacion;

public static class DetectorProgramas
{
    public static bool MencionaProgramaAjeno(string textoNormalizado, IReadOnlyCollection<string> programasPropios, DirectorioAcademico directorio)
    {
        var tokens = TokenizadorTexto.Tokenizar(textoNormalizado);
        return directorio.Programas
            .Where(programa => !programasPropios.Contains(programa.Id))
            .Any(programa => Menciona(tokens, programa.Id) || Menciona(tokens, programa.Nombre));
    }

    private static bool Menciona(IReadOnlyList<TokenTexto> tokens, string texto) =>
        TokenizadorTexto.BuscarSecuencia(tokens, TokenizadorTexto.Valores(texto)) >= 0;
}

namespace TutorFlow.Core.Autorizacion;

public sealed class PoliticaAcceso
{
    public DecisionAcceso EvaluarIdentidad(Usuario usuario, DirectorioAcademico directorio) =>
        ExisteIdentidad(usuario, directorio)
            ? DecisionAcceso.Permitir()
            : DecisionAcceso.Denegar(MotivoDenegacion.IdentidadInvalida);

    public DecisionAcceso EvaluarPregunta(Usuario usuario, string pregunta, DirectorioAcademico directorio)
    {
        var texto = NormalizadorTexto.Normalizar(pregunta);
        var motivo = MotivoTercero(usuario, texto, directorio)
            ?? MotivoPrograma(usuario, texto, directorio)
            ?? MotivoAgregado(usuario, texto);
        return motivo is { } denegado ? DecisionAcceso.Denegar(denegado) : DecisionAcceso.Permitir();
    }

    public DecisionAcceso EvaluarLecturaEstudiante(Usuario usuario, string estudianteId, DirectorioAcademico directorio) =>
        PuedeLeerEstudiante(usuario, estudianteId, directorio)
            ? DecisionAcceso.Permitir()
            : DecisionAcceso.Denegar(MotivoDenegacion.HerramientaIdAjeno);

    public IReadOnlyList<string> ProgramasAutorizados(Usuario usuario, DirectorioAcademico directorio) =>
        AmbitoPersonal.ProgramasDe(usuario, directorio);

    private static bool ExisteIdentidad(Usuario usuario, DirectorioAcademico directorio) => usuario.Rol switch
    {
        Rol.Estudiante => Identificadores.EsIdEstudiante(usuario.Id) && directorio.Estudiantes.Any(e => e.Id == usuario.Id),
        Rol.Coordinador => Identificadores.EsIdCoordinador(usuario.Id) && directorio.Coordinadores.Any(c => c.Id == usuario.Id),
        _ => false
    };

    private bool PuedeLeerEstudiante(Usuario usuario, string estudianteId, DirectorioAcademico directorio)
    {
        var estudiante = directorio.Estudiantes.FirstOrDefault(e => e.Id == estudianteId);
        if (estudiante is null || !Identificadores.EsIdEstudiante(estudianteId))
        {
            return false;
        }

        return usuario.Rol == Rol.Estudiante
            ? usuario.Id == estudianteId
            : ProgramasAutorizados(usuario, directorio).Contains(estudiante.ProgramaId);
    }

    private static MotivoDenegacion? MotivoTercero(Usuario usuario, string texto, DirectorioAcademico directorio) =>
        DetectorTerceros.MencionaTercero(usuario, texto, directorio) ? MotivoDenegacion.TerceroMencionado : null;

    private MotivoDenegacion? MotivoPrograma(Usuario usuario, string texto, DirectorioAcademico directorio) =>
        usuario.Rol == Rol.Coordinador && DetectorProgramas.MencionaProgramaAjeno(texto, ProgramasAutorizados(usuario, directorio), directorio)
            ? MotivoDenegacion.ProgramaAjeno
            : null;

    private static MotivoDenegacion? MotivoAgregado(Usuario usuario, string texto) =>
        usuario.Rol == Rol.Estudiante && DetectorAgregados.PideAgregados(texto) ? MotivoDenegacion.Agregado : null;
}

