{
    private DateTimeOffset _ahora = new(2026, 11, 22, 12, 0, 0, TimeSpan.Zero);

    public DateTimeOffset AhoraUtc => _ahora;

    public void Avanzar(TimeSpan intervalo) => _ahora += intervalo;
