        using var fabrica = new FabricaApi(configuracion: configuracion);

        var respuestas = await PreguntarConCadaId(fabrica, CuatroIds.Take(3));

        Assert.All(respuestas, r => Assert.Equal(200, r.Estado));
    }
}

