    {
        _proveedor = proveedor;
        _logger = logger;
    }

    public Task StartAsync(CancellationToken cancellationToken)
    {
        if (_proveedor.Adaptador == AdaptadorLlm.NoConfigurado)
        {
            _logger.LogError("Configuración del LLM incompleta: la llave tiene un prefijo desconocido y falta LLM_URL_BASE. Las preguntas que necesitan el LLM responderán 503.");
            return Task.CompletedTask;
        }

        _logger.LogInformation(
            "Proveedor del LLM: {Proveedor}, adaptador {Adaptador}, modelo {Modelo}, precio desconocido: {PrecioDesconocido}.",
            _proveedor.Proveedor,
            _proveedor.Adaptador,
            _proveedor.Modelo,
            _proveedor.PrecioDesconocido);
        return Task.CompletedTask;
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;
}

