    {
        var llamadas = respuesta.Messages
            .SelectMany(mensaje => mensaje.Contents)
            .OfType<FunctionCallContent>()
            .Select(llamada => new LlamadaHerramienta(llamada.CallId, llamada.Name, JsonSerializer.Serialize(llamada.Arguments ?? new Dictionary<string, object?>())))
            .ToList();
        var uso = new UsoTokens((int)(respuesta.Usage?.InputTokenCount ?? 0), (int)(respuesta.Usage?.OutputTokenCount ?? 0));
        var texto = respuesta.Text;
        return new RespuestaLlm(string.IsNullOrEmpty(texto) ? null : texto, llamadas, uso, respuesta.FinishReason == ChatFinishReason.ContentFilter);
    }
